import{at as e,n as t,rt as n,xt as r}from"./chunks/framework.DIOWbp6D.js";var i=JSON.parse(`{"title":"Extensions","description":"","frontmatter":{},"headers":[],"relativePath":"ecosystem/extensions.md","filePath":"ecosystem/extensions.md"}`),a={name:`ecosystem/extensions.md`};function o(t,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[e(`<h1 id="extensions" tabindex="-1">Extensions <a class="header-anchor" href="#extensions" aria-label="Permalink to “Extensions”">​</a></h1><p><code>ext-*</code> crates package Handl operations as <strong>dynamic extensions</strong> — <code>libhnl_ext_*.so</code>/<code>.dylib</code>/<code>.dll</code> shared libraries discovered at runtime via <code>HANDL_EXT_DIR</code> or <code>~/.handl/ext</code>. Each extension wraps one tool family so <code>hnl</code> stays a dumb host: the CLI links the extension, the extension links the engine.</p><table tabindex="0"><thead><tr><th>Extension</th><th>Provides</th></tr></thead><tbody><tr><td><a href="https://github.com/handl-lang/ext-eval" target="_blank" rel="noreferrer">ext-eval</a></td><td><code>hnl run</code> / <code>hnl eval</code> — program evaluation</td></tr><tr><td><a href="https://github.com/handl-lang/ext-compile" target="_blank" rel="noreferrer">ext-compile</a></td><td><code>hnl compile</code> — compiler front end</td></tr><tr><td><a href="https://github.com/handl-lang/ext-transform" target="_blank" rel="noreferrer">ext-transform</a></td><td><code>hnl transform</code> — transform runner</td></tr><tr><td><a href="https://github.com/handl-lang/ext-typecheck" target="_blank" rel="noreferrer">ext-typecheck</a></td><td><code>hnl typecheck</code> / <code>hnl check</code></td></tr><tr><td><a href="https://github.com/handl-lang/ext-fmt" target="_blank" rel="noreferrer">ext-fmt</a></td><td><code>hnl fmt</code> — formatter</td></tr><tr><td><a href="https://github.com/handl-lang/ext-lint" target="_blank" rel="noreferrer">ext-lint</a></td><td><code>hnl lint</code> — canonical linter</td></tr><tr><td><a href="https://github.com/handl-lang/ext-test" target="_blank" rel="noreferrer">ext-test</a></td><td><code>hnl test</code> — test runner</td></tr><tr><td><a href="https://github.com/handl-lang/ext-codegen" target="_blank" rel="noreferrer">ext-codegen</a></td><td><code>hnl codegen</code> — SDK/FFI generation pipeline</td></tr><tr><td><a href="https://github.com/handl-lang/ext-codemod" target="_blank" rel="noreferrer">ext-codemod</a></td><td><code>hnl codemod</code> — declarative codemod pipeline</td></tr><tr><td><a href="https://github.com/handl-lang/ext-kit" target="_blank" rel="noreferrer">ext-kit</a></td><td><code>hnl kit</code> + <code>hnl gen-grammar</code> — kit tooling</td></tr><tr><td><a href="https://github.com/handl-lang/ext-plugin" target="_blank" rel="noreferrer">ext-plugin</a></td><td><code>hnl plugin</code> — plugin management</td></tr></tbody></table><p>The same operation also exists as a <code>tool-*</code> engine crate — the extension is a thin packaging of it. Building an extension is a normal Rust crate implementing the <code>hnl-ext</code> ABI; dropping the built library into the ext dir is the entire install step.</p>`,4)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};